#include<bits/stdc++.h>using namespace std; int main(){    int t;    cin >> t;    while(t--)    {        int a,b,c,d;        cin >> a >> b >> c >> d;        int fir = max(a,b);        int firmin = min(a,b);        int sec = max(c,d);        int secmin = min(c,d);        int saved = max(firmin,secmin);        if(fir > saved && sec > saved)        {            cout << "YES" << endl;        }        else        {            cout <<"NO" << endl;        }    }}